{"variables":{},"query":"{
  instances(where: {deleted_at: {_is_null: true}, visible: {_eq: true}}) {
    id
    name
    platform_domain
    platform_id
    campaign_instances_aggregate(where: {campaign_id: {_eq: 2595}}) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    __typename
  }
}"}

{"operationName":"getData","variables":{"offset":0,"limit":20},"query":"query getData($offset: Int!, $limit: Int!) {
  instances_aggregate(
    where: {platform_id: {_in: [1]}, deleted_at: {_is_null: true}, visible: {_eq: true}}
    order_by: {created_at: desc}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  instances(
    offset: $offset
    limit: $limit
    where: {platform_id: {_in: [1]}, deleted_at: {_is_null: true}, visible: {_eq: true}}
    order_by: {created_at: desc}
  ) {
    id
    name
    platform_id
    campaign_instances(where: {campaign_id: {_eq: 2595}}) {
      id
      instance_id
      handle: platform_linked_handle
      need_sync
      platform_linked_id
      __typename
    }
    domain
    platform_domain
    platform {
      name
      __typename
    }
    __typename
  }
}"}
